// -----------------------------------------------------------------------------
// @file: lib/templates/index.ts
// @purpose: Free downloadable templates at /templates. The files live in
//           public/templates and are generated by the scripts noted in
//           public/templates/README.md; each pairs with a guide and a tool.
// -----------------------------------------------------------------------------

export type TemplatePreview =
  | { kind: "image"; src: string; width: number; height: number; alt: string }
  | { kind: "calendar" };

export type FreeTemplate = {
  slug: string;
  title: string;
  /** Search title, about 50 characters; " | brandbite" is added after it. */
  seoTitle: string;
  description: string;
  /** Public path of the file. */
  file: string;
  format: "Word" | "Excel" | "PowerPoint";
  extension: "docx" | "xlsx" | "pptx";
  opensIn: string[];
  preview: TemplatePreview;
  inside: string[];
  howTo: string[];
  guide?: { href: string; label: string };
  tool?: { href: string; label: string };
  updatedOn: string;
};

